mapper.select:

 where (r.del_flag = '0' or r.del_flag = '2')
   and r.rule_type = 'ORDER'




   and r.rule_id in #{v}


   and r.rule_no in #{v}



   and strpos(lower(r.rule_name), #{f.keyword}) > 0


   and r.enabled = #{f.enabled}


   and coalesce(r.config->>'orderType', 'WITHDRAW') in
       #{v}


   and r.config->>'amountMode' in #{v}


   and r.config->>'triggerAt' in #{v}


   and r.level in #{v}



   and coalesce(jsonb_typeof(r.config->'channelScope'), 'null') = 'null'


   and r.config->'channelScope'->>'type' = 'PROMOTER'
   and r.config->'channelScope'->>'promoterId' = #{f.promoterId}


   and r.config->'channelScope'->>'type' = 'CHANNEL'
   and r.config->'channelScope'->>'promoterId' = #{f.promoterId}
   and r.config->'channelScope'->>'channelId' = #{f.channelId}



   and r.notify_enabled = #{f.notifyEnabled}


   and exists (select 1 from jsonb_array_elements(r.notify_chats) fc
                where fc->>'chatId' in #{v})


   and lower(u.email) = #{f.ownerEmail}


   and (r.config->>'amountThreshold')::numeric >= #{f.amountMin}


   and (r.config->>'amountThreshold')::numeric <= #{f.amountMax}


   and r.version > #{f.sinceVersion}


   and r.update_time >= #{f.updatedFrom}


   and r.update_time < #{f.updatedTo}


	 order by r.update_time desc, r.rule_id desc
	 order by r.rule_no
	 order by r.version, r.rule_id


where r.del_flag = '0'
  and r.rule_type = 'ORDER'
  and r.rule_id = #{ruleId}


where r.del_flag = '0'
  and r.rule_type = 'ORDER'
  and r.rule_no = #{ruleNo}

mapper.insert:
insert into monitor_rule (
    site_code, rule_no, rule_type, owner_user_id, rule_name, description, level,
    notify_enabled, notify_chat_id, notify_chat_name, notify_chats, currency, config,
    enabled, paused_at, del_flag, create_by, create_time, update_by, update_time
) values (
    #{siteCode}, #{ruleNo}, 'ORDER', #{ownerUserId}, #{ruleName}, #{description,jdbcType=VARCHAR}, #{level},
    #{notifyEnabled}, #{notifyChatId,jdbcType=VARCHAR}, #{notifyChatName,jdbcType=VARCHAR},
    coalesce(#{notifyChats,jdbcType=VARCHAR}, '[]')::jsonb, #{currency}, #{config}::jsonb,
    #{enabled}, #{pausedAt,jdbcType=TIMESTAMP}, '0', #{createBy}, #{createTime}, #{createBy}, #{createTime}
)
